select.trim:
SELECT decode(total.IS_CANCEL,#{YON_Y},#{STATUS_VALID_CX},#{STATUS_VALID_YX}) statusValid, total.PORTFOLIO_ID portfolioId, pp.PORTFOLIO_NAME portfolioName, total.FINPROD_ID finprodId, nvl(fp.FINPROD_ABBR,fp.FINPROD_NAME) finprodName, total.TOTLE_TRADE_ID totleTradeId, total.TRADE_DATE transferDate, total.PRIN_AMT prinAmt, total.INT_AMT intAmt, total.TRADE_AMT tradeAmt, total.COUNTER_ID counterId, total.REMARK, paTotal.THEORY_PENALTY_INT theoryPenaltyInt, paTotal.THEORY_PRIN theoryPrin, paTotal.THEORY_INT theoryInt, addTotal.PENALTY_INTAMT penaltyInt FROM TRD_FIN_PRODUCT_DEAL_TOTAL total LEFT JOIN PA_TRD_FIN_PRODUCT_DEAL_TOTAL paTotal on paTotal.TOTLE_TRADE_ID = total.TOTLE_TRADE_ID LEFT JOIN TRD_DEAL_TOTAL_ADD addTotal on addTotal.TOTLE_TRADE_ID = total.TOTLE_TRADE_ID LEFT JOIN PTL_PORTFOLIO pp on pp.PORTFOLIO_ID = total.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT fp on fp.FINPROD_ID = total.FINPROD_ID where total.PS=#{PS_MC} and paTotal.PA_BUSS_TYPE = #{PINAN_BUSINESS_TYPE_YDQZCZR} and total.TRADE_STATUS = #{TRADE_STATUS_CS}
and (
total.IS_CANCEL = #{YON_N}
or
total.IS_CANCEL = #{YON_Y}
)
union all
SELECT #{STATUS_VALID_LCZ} statusValid, total.PORTFOLIO_ID portfolioId, pp.PORTFOLIO_NAME portfolioName, total.FINPROD_ID finprodId, nvl(fp.FINPROD_ABBR,fp.FINPROD_NAME) finprodName, total.TOTLE_TRADE_ID totleTradeId, total.TRADE_DATE transferDate, total.PRIN_AMT prinAmt, total.INT_AMT intAmt, total.TRADE_AMT tradeAmt, total.COUNTER_ID counterId, total.REMARK, paTotal.THEORY_PENALTY_INT theoryPenaltyInt, paTotal.THEORY_PRIN theoryPrin, paTotal.THEORY_INT theoryInt, addTotal.PENALTY_INTAMT penaltyInt FROM WFL_TRD_FIN_PRODUCT_DEAL_TOTAL total LEFT JOIN WFL_PA_TRD_FIN_DEAL_TOTAL paTotal on paTotal.TOTLE_TRADE_ID = total.TOTLE_TRADE_ID LEFT JOIN WFL_TRD_DEAL_TOTAL_ADD addTotal on addTotal.TOTLE_TRADE_ID = total.TOTLE_TRADE_ID LEFT JOIN PTL_PORTFOLIO pp on pp.PORTFOLIO_ID = total.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT fp on fp.FINPROD_ID = total.FINPROD_ID where total.PS=#{PS_MC} and paTotal.PA_BUSS_TYPE = #{PINAN_BUSINESS_TYPE_YDQZCZR} and total.TRADE_STATUS = #{TRADE_STATUS_CS} and total.IS_CANCEL = #{YON_N}
